// And groups predicates with the AND operator between them.
func And(predicates ...predicate.Allowance) predicate.Allowance {
	return predicate.Allowance(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.Allowance) predicate.Allowance {
	return predicate.Allowance(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.Allowance) predicate.Allowance {
	return predicate.Allowance(sql.NotPredicates(p))
}
